/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { GF, Poly, Rational, Sym, add, cancel, factor, gcd, mul, pow } from '../../../src';
import { sympyStr } from '../../sympy-str';

describe("doctests of sympy.polys.domains.finitefield", () => {
  // a result object that did not come from the library
  //   p.domain
  //   => ZZ
  it.todo("p.domain");
  // a result object that did not come from the library
  //   p2.domain
  //   => GF(2)
  it.todo("p2.domain");
  it("factor(x**2 + 1)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), { deep: false, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('x**2 + 1');
  });
  it("factor(x**2 + 1, modulus=2)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), { modulus: 2n, deep: false, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('(x + 1)**2');
  });
  it("factor(x**2 + 1, domain=GF(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), { domain: GF(2, true), deep: false, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('(x + 1)**2');
  });
  it("factor(x**2 + 1, domain='GF(2)')", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), { domain: 'GF(2)', deep: false, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('(x + 1)**2');
  });
  it("cancel((x**2 + 1)/(x + 1))", () => {
    const x = new Sym('x');
    expect(sympyStr(cancel(mul(pow(add(Rational.of(1n, 1n, { gcd: 1n }), x), Rational.of(-1n, 1n, { gcd: 1n })), add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n })))), { greedy: true }))).toBe('(x**2 + 1)/(x + 1)');
  });
  it("cancel((x**2 + 1)/(x + 1), domain=GF(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(cancel(mul(pow(add(Rational.of(1n, 1n, { gcd: 1n }), x), Rational.of(-1n, 1n, { gcd: 1n })), add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n })))), { domain: GF(2, true), greedy: true }))).toBe('x + 1');
  });
  it("gcd(x**2 + 1, x + 1)", () => {
    const x = new Sym('x');
    expect(sympyStr(gcd(add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), add(Rational.of(1n, 1n, { gcd: 1n }), x), {}))).toBe('1');
  });
  it("gcd(x**2 + 1, x + 1, domain=GF(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(gcd(add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), add(Rational.of(1n, 1n, { gcd: 1n }), x), { domain: GF(2, true) }))).toBe('x + 1');
  });
  it("x * y", () => {
    expect(sympyStr(GF(5n, true)['new'](3n).mul(GF(5n, true)['new'](2n)))).toBe('1 mod 5');
  });
  it("x / y", () => {
    expect(sympyStr(GF(5n, true)['new'](3n).div(GF(5n, true)['new'](2n)))).toBe('4 mod 5');
  });
  it("z**2", () => {
    expect(sympyStr(GF(9n, true)['new'](3n).pow(2))).toBe('0 mod 9');
  });
  it("p", () => {
    const x = new Sym('x');
    expect(sympyStr(Poly.fromExpr(add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), [], {}))).toBe('Poly(x**2 + 1, x, domain=\'ZZ\')');
  });
  it("p2", () => {
    const x = new Sym('x');
    expect(sympyStr(Poly.fromExpr(add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), [], { modulus: 2n }))).toBe('Poly(x**2 + 1, x, modulus=2)');
  });
  it("K", () => {
    expect(sympyStr(GF(Rational.of(5n, 1n, { gcd: 1n })))).toBe('GF(5)');
  });
});
